package com.odelly.pypet;

import android.app.Activity;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import java.util.List;

/** Full-screen PyPet town. Academy teaches Python; Home cares for pets; Park is recreation. */
public final class LivingWorldView {
    private LivingWorldView() {}
    public static void show(Activity a) {
        final World world=new World(a);
        FrameLayout root=new FrameLayout(a); root.setBackgroundColor(Color.rgb(151,196,119)); root.addView(world,new FrameLayout.LayoutParams(-1,-1));
        TextView title=overlay(a,"🌎 "+PypetProfileManager.townName(a)+" • PyPet WORLD",19); root.addView(title,new FrameLayout.LayoutParams(-1,48,Gravity.TOP));
        TextView help=overlay(a,"Pinch to zoom • drag to explore • tap a building to do its activity",12); FrameLayout.LayoutParams hp=new FrameLayout.LayoutParams(-1,34,Gravity.TOP);hp.topMargin=48;root.addView(help,hp);
        LinearLayout controls=new LinearLayout(a);controls.setGravity(Gravity.CENTER);controls.setPadding(5,3,5,3);controls.setBackgroundColor(Color.argb(225,250,247,232));
        Button out=btn(a,"−"),reset=btn(a,"🌎 Reset"),custom=btn(a,"🛠 Customize"),in=btn(a,"+"),profile=btn(a,"👤");
        controls.addView(out,new LinearLayout.LayoutParams(50,56));controls.addView(reset,new LinearLayout.LayoutParams(0,56,1));controls.addView(custom,new LinearLayout.LayoutParams(0,56,1));controls.addView(in,new LinearLayout.LayoutParams(50,56));controls.addView(profile,new LinearLayout.LayoutParams(62,56));
        root.addView(controls,new FrameLayout.LayoutParams(-1,62,Gravity.BOTTOM));
        out.setOnClickListener(v->world.zoomBy(.86f)); in.setOnClickListener(v->world.zoomBy(1.16f)); reset.setOnClickListener(v->world.reset()); profile.setOnClickListener(v->PypetProfileView.show(a,false,()->show(a))); custom.setOnClickListener(v->world.toggleCustomize());
        a.setContentView(root);
    }
    private static TextView overlay(Activity a,String s,float z){TextView v=new TextView(a);v.setText(s);v.setTextSize(z);v.setGravity(Gravity.CENTER);v.setTextColor(Color.rgb(39,53,42));v.setBackgroundColor(Color.argb(225,250,247,232));return v;}
    private static Button btn(Activity a,String s){Button b=new Button(a);b.setText(s);b.setAllCaps(false);return b;}

    private static final class World extends View {
        private static final float W=2400f,H=2400f,MIN=.62f,MAX=3f;
        private final Activity a; private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG),t=new Paint(Paint.ANTI_ALIAS_FLAG); private final RectF[] hit=new RectF[6];
        private final String[] names={"HOME","PYTHON ACADEMY","MARKET","WORKSHOP","PARK","LIBRARY"};
        private final String[] ids={"home","academy","market","workshop","park","library"};
        private float zoom=1f,ox,oy,lastX,lastY,downX,downY; private boolean moved,customize; private int selected=-1;
        World(Activity a){super(a);this.a=a;t.setTypeface(Typeface.DEFAULT_BOLD);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
        void reset(){zoom=1f;ox=oy=0;PetWorldAI.reset(a,260,420);invalidate();}
        void zoomBy(float f){zoom=Math.max(MIN,Math.min(MAX,zoom*f));invalidate();}
        void toggleCustomize(){customize=!customize;selected=-1;invalidate();}
        @Override protected void onDraw(Canvas c){c.drawColor(Color.rgb(151,196,119));float fit=Math.max(getWidth()/W,getHeight()/H)*zoom;c.save();c.translate(getWidth()/2f+ox,getHeight()/2f+oy);c.scale(fit,fit);drawWorld(c);c.restore();postInvalidateDelayed(120);}
        private void drawWorld(Canvas c){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(151,196,119));c.drawRect(-1200,-1200,1200,1200,p);terrain(c);roads(c);lots(c);drawPark(c);drawBuildings(c);trees(c);trophies(c);placements(c);pet(c);t.setTextAlign(Paint.Align.CENTER);t.setTextSize(50);t.setColor(Color.rgb(43,70,45));c.drawText(PypetProfileManager.townName(a),0,-1090,t);t.setTextSize(24);c.drawText("Your accomplishments live here",0,-1038,t);if(customize)drawCustomizeHud(c);}
        private void terrain(Canvas c){p.setColor(Color.rgb(174,207,139));for(int x=-1100;x<=1100;x+=220)for(int y=-1120;y<=1120;y+=260)c.drawCircle(x+((y/260)%2)*35,y,4,p);}
        private void roads(Canvas c){p.setColor(Color.rgb(216,205,177));c.drawRect(-160,-1200,160,1200,p);c.drawRect(-1200,-160,1200,160,p);p.setColor(Color.rgb(58,59,57));c.drawRect(-98,-1200,98,1200,p);c.drawRoundRect(-1200,-98,1200,98,24,24,p);p.setColor(Color.rgb(229,219,181));for(int y=-1120;y<=1120;y+=170)if(Math.abs(y)>135)c.drawRoundRect(-5,y,5,y+92,3,3,p);for(int x=-1120;x<=1120;x+=170)if(Math.abs(x)>135)c.drawRoundRect(x,-5,x+92,5,3,3,p);p.setColor(Color.rgb(190,185,165));c.drawRect(-185,-1200,-160,1200,p);c.drawRect(160,-1200,185,1200,p);c.drawRect(-1200,-185,1200,-160,p);c.drawRect(-1200,160,1200,185,p);}
        private void lots(Canvas c){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(4);p.setColor(Color.argb(105,255,255,255));lot(c,-910,-990,-250,-560);lot(c,250,-990,910,-560);lot(c,-910,250,-250,670);lot(c,250,250,910,670);lot(c,-910,720,-250,1090);lot(c,250,720,910,1090);p.setStyle(Paint.Style.FILL);}
        private void lot(Canvas c,float l,float top,float r,float bot){c.drawRoundRect(l,top,r,bot,28,28,p);}
        private void drawBuildings(Canvas c){drawBuilding(c,0,Color.rgb(164,83,63));drawBuilding(c,1,Color.rgb(64,95,147));drawBuilding(c,2,Color.rgb(209,143,55));drawBuilding(c,3,Color.rgb(48,116,137));drawBuilding(c,5,Color.rgb(103,74,137));}
        private void drawBuilding(Canvas c,int i,int roof){WorldLayoutManager.Item q=WorldLayoutManager.get(a,ids[i]);hit[i]=new RectF(q.x-q.w*.5f,q.y-q.h*.5f,q.x+q.w*.5f,q.y+q.h*.5f);c.save();c.translate(q.x,q.y);c.rotate(q.rotation);float l=-q.w*.5f,top=-q.h*.5f,r=q.w*.5f,b=q.h*.5f; p.setShadowLayer(14,0,7,Color.argb(70,0,0,0));p.setColor(Color.rgb(246,241,225));c.drawRoundRect(l,top,r,b,18,18,p);p.clearShadowLayer();p.setColor(roof);Path roofPath=new Path();roofPath.moveTo(l-18,top+8);roofPath.lineTo(0,top-q.h*.28f);roofPath.lineTo(r+18,top+8);roofPath.close();c.drawPath(roofPath,p);door(c,0,b);String label=names[i];if(i==0){window(c,l+55,top+70,70,58);window(c,r-125,top+70,70,58);}else if(i==1){for(int row=0;row<2;row++)for(int col=0;col<5;col++)window(c,l+25+col*82,top+38+row*62,48,38);p.setColor(Color.rgb(74,106,150));c.drawRoundRect(l+28,b-105,r-28,b-75,10,10,p);t.setTextSize(14);t.setColor(Color.WHITE);c.drawText("CODE • LEARN • BUILD",0,b-84,t);}else if(i==2){for(int x=0;x<3;x++)window(c,l+45+x*120,top+60,60,45);p.setColor(Color.rgb(222,83,63));c.drawRect(l+40,b-105,r-40,b-80,p);}else if(i==3){for(int x=0;x<2;x++)window(c,l+55+x*180,top+55,75,52);p.setColor(Color.rgb(122,88,55));c.drawRect(l+50,top+135,r-50,top+165,p);for(int x=0;x<3;x++){p.setColor(Color.rgb(216,171,72));c.drawCircle(l+90+x*125,top+118,16,p);}}else {for(int x=0;x<3;x++)window(c,l+48+x*112,top+50,64,46);}t.setTextAlign(Paint.Align.CENTER);t.setTextSize(18);t.setColor(Color.rgb(45,52,47));c.drawText(label,0,top-q.h*.31f,t);if(customize&&selected==i){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(12);p.setColor(Color.rgb(255,235,70));c.drawRoundRect(l-12,top-12,r+12,b+12,22,22,p);p.setStyle(Paint.Style.FILL);}c.restore();}
        private void drawPark(Canvas c){WorldLayoutManager.Item q=WorldLayoutManager.get(a,"park");hit[4]=new RectF(q.x-q.w*.5f,q.y-q.h*.5f,q.x+q.w*.5f,q.y+q.h*.5f);c.save();c.translate(q.x,q.y);c.rotate(q.rotation);float l=-q.w*.5f,top=-q.h*.5f,r=q.w*.5f,b=q.h*.5f;p.setShadowLayer(10,0,5,Color.argb(60,0,0,0));p.setColor(Color.rgb(83,166,86));c.drawRoundRect(l,top,r,b,40,40,p);p.clearShadowLayer();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(12);p.setColor(Color.rgb(237,224,178));c.drawRoundRect(l+15,top+15,r-15,b-15,30,30,p);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(224,210,171));c.drawRoundRect(l+50,top+115,r-50,top+170,18,18,p);bench(c,l+130,top+215);bench(c,l+600,top+215);pond(c,l+85,top+250);playground(c,r-360,top+90);for(int j=0;j<5;j++)tree(c,l+100+j*155,top+70,30);t.setColor(Color.rgb(244,231,180));c.drawRoundRect(-155,top+20,155,top+75,12,12,p);t.setTextSize(23);t.setColor(Color.rgb(48,95,48));t.setTextAlign(Paint.Align.CENTER);c.drawText("🌳 PARK • PLAY",0,top+57,t);if(customize&&selected==4){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(12);p.setColor(Color.rgb(255,235,70));c.drawRoundRect(l-12,top-12,r+12,b+12,42,42,p);p.setStyle(Paint.Style.FILL);}c.restore();}
        private void door(Canvas c,float x,float b){p.setColor(Color.rgb(103,74,54));c.drawRoundRect(x-24,b-68,x+24,b,6,6,p);p.setColor(Color.rgb(232,204,117));c.drawCircle(x+11,b-34,3.5f,p);p.setColor(Color.rgb(203,195,171));c.drawRect(x-34,b,x+34,b+9,p);}
        private void window(Canvas c,float x,float y,float w,float h){p.setColor(Color.rgb(71,133,166));c.drawRoundRect(x,y,x+w,y+h,5,5,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);p.setColor(Color.rgb(238,241,224));c.drawRect(x,y,x+w,y+h,p);c.drawLine(x+w/2,y,x+w/2,y+h,p);c.drawLine(x,y+h/2,x+w,y+h/2,p);p.setStyle(Paint.Style.FILL);}
        private void bench(Canvas c,float x,float y){p.setColor(Color.rgb(118,78,47));c.drawRoundRect(x-55,y,x+55,y+15,5,5,p);c.drawRect(x-40,y+15,x-28,y+42,p);c.drawRect(x+28,y+15,x+40,y+42,p);}
        private void pond(Canvas c,float x,float y){p.setColor(Color.rgb(58,155,198));c.drawOval(x,y,x+230,y+110,p);p.setColor(Color.rgb(150,214,232));c.drawOval(x+35,y+25,x+135,y+75,p);}
        private void playground(Canvas c,float x,float y){p.setColor(Color.rgb(210,78,64));c.drawRoundRect(x,y,x+110,y+25,7,7,p);c.drawRect(x+12,y+20,x+25,y+95,p);c.drawRect(x+85,y+20,x+98,y+60,p);p.setColor(Color.rgb(103,73,51));p.setStrokeWidth(8);c.drawLine(x+15,y+120,x+125,y+120,p);c.drawLine(x+25,y+120,x,y+180,p);c.drawLine(x+115,y+120,x+140,y+180,p);p.setColor(Color.rgb(219,116,57));c.drawRoundRect(x+30,y+178,x+90,y+190,5,5,p);}
        private void trees(Canvas c){for(int i=-5;i<=5;i++)tree(c,i*280,-360+i*115,31);}
        private void tree(Canvas c,float x,float y,float r){p.setColor(Color.rgb(113,76,49));c.drawRect(x-7,y+r*.35f,x+7,y+r*1.2f,p);p.setColor(Color.rgb(47,127,57));c.drawCircle(x,y,r,p);p.setColor(Color.rgb(78,154,75));c.drawCircle(x-r*.35f,y-r*.2f,r*.55f,p);}
        private void trophies(Canvas c){int k=0;for(PypetAchievementManager.Trophy tr:PypetAchievementManager.trophies()){if(!PypetAchievementManager.hasTrophy(a,tr.id))continue;float x=-1050+(k%7)*300,y=1130+(k/7)*80;trophy(c,x,y,tr.name);k++;}}
        private void trophy(Canvas c,float x,float y,String s){p.setColor(Color.rgb(224,181,64));c.drawRoundRect(x-24,y-30,x+24,y+12,7,7,p);c.drawCircle(x,y-8,15,p);p.setColor(Color.rgb(117,81,43));c.drawRect(x-5,y+10,x+5,y+31,p);c.drawRect(x-35,y+29,x+35,y+38,p);t.setTextSize(12);t.setColor(Color.rgb(255,250,224));t.setTextAlign(Paint.Align.CENTER);c.drawText(s,x,y+60,t);}
        private void placements(Canvas c){List<WorldPlacementManager.Placement> list=WorldPlacementManager.all(a);for(WorldPlacementManager.Placement q:list){c.save();c.translate(q.x,q.y);c.rotate(q.rotation);c.scale(q.scale,q.scale);item(c,q.id);c.restore();}}
        private void item(Canvas c,String id){if(id.contains("bench")){bench(c,0,0);return;}if(id.contains("tree")){tree(c,0,0,34);return;}if(id.contains("trophy")){trophy(c,0,0,"🏆");return;}if(id.contains("flower")){for(int i=-2;i<=2;i++){p.setColor(Color.rgb(67,143,65));c.drawRect(i*22-2,0,i*22+2,25,p);p.setColor(Color.rgb(235,113,139));c.drawCircle(i*22,0,7,p);}return;}p.setColor(Color.rgb(190,151,91));c.drawRoundRect(-36,-28,36,28,10,10,p);}
        private void pet(Canvas c){PetWorldAI.State s=PetWorldAI.tick(a,-1080,1080,-1080,1080);p.setColor(Color.argb(55,0,0,0));c.drawOval(s.x-34,s.y-3,s.x+34,s.y+12,p);c.save();c.translate(s.x,s.y);PetBodyModel b=PetBodyModel.forVariant(PetEvolutionManager.current(a));float bob=s.walking?(float)Math.sin(s.stepPhase)*2:0;p.setColor(b.bodyTone);c.drawOval(-34,-55+bob,34,-8+bob,p);p.setColor(b.accentTone);c.drawCircle(0,-75+bob,25,p);p.setColor(Color.rgb(65,45,35));c.drawCircle(-9,-80+bob,3,p);c.drawCircle(9,-80+bob,3,p);p.setStrokeWidth(7);c.drawLine(-20,-10,-25,0,p);c.drawLine(20,-10,25,0,p);c.restore();t.setTextAlign(Paint.Align.CENTER);t.setTextSize(18);t.setColor(Color.DKGRAY);c.drawText(PetEvolutionManager.name(a)+" • Lv "+PetEvolutionManager.current(a).level,s.x,s.y+92,t);}
        private void drawCustomizeHud(Canvas c){p.setColor(Color.argb(235,255,255,255));c.drawRoundRect(-1080,-1160,-250,-1030,24,24,p);t.setTextAlign(Paint.Align.LEFT);t.setTextSize(28);t.setColor(Color.rgb(45,60,48));c.drawText("CUSTOMIZE WORLD",-1035,-1120,t);t.setTextSize(19);c.drawText(selected<0?"Tap a building or park, then drag it":"Selected: "+names[selected]+" • drag to move",-1035,-1080,t);}
        @Override public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){downX=lastX=e.getX();downY=lastY=e.getY();moved=false;return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){float dx=e.getX()-lastX,dy=e.getY()-lastY;if(Math.abs(e.getX()-downX)+Math.abs(e.getY()-downY)>18)moved=true;if(customize&&selected>=0){float fit=Math.max(getWidth()/W,getHeight()/H)*zoom;float wx=(e.getX()-getWidth()/2f-ox)/fit,wy=(e.getY()-getHeight()/2f-oy)/fit;String id=ids[selected];WorldLayoutManager.move(a,id,wx,wy);invalidate();}else{ox+=dx;oy+=dy;lastX=e.getX();lastY=e.getY();invalidate();}return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){if(customize){if(!moved){float fit=Math.max(getWidth()/W,getHeight()/H)*zoom;float wx=(e.getX()-getWidth()/2f-ox)/fit,wy=(e.getY()-getHeight()/2f-oy)/fit;for(int i=0;i<hit.length;i++)if(hit[i]!=null&&hit[i].contains(wx,wy)){selected=i;invalidate();return true;}if(selected>=0){WorldLayoutManager.rotate(a,ids[selected],15);invalidate();return true;}}return true;}if(moved)return true;float fit=Math.max(getWidth()/W,getHeight()/H)*zoom;float wx=(e.getX()-getWidth()/2f-ox)/fit,wy=(e.getY()-getHeight()/2f-oy)/fit;for(int i=0;i<hit.length;i++)if(hit[i]!=null&&hit[i].contains(wx,wy)){BuildingEventManager.open(a,names[i]);return true;}return true;}return true;}
    }
}
